document.addEventListener('DOMContentLoaded', () => {
    const topbar=document.querySelector('[data-admin-topbar="true"]');

    if(!topbar) return;

    /* Remove any helper generated by form-help.js around global search. */
    const search=
        topbar.querySelector('.eh-admin-topbar__search input[name="q"]') ||
        topbar.querySelector('input[type="search"]');

    if(search){
        const searchForm=search.closest('form');

        if(searchForm){
            [...searchForm.querySelectorAll('*')].forEach((node)=>{
                if(node===search || node.closest('button')) return;

                const text=(node.textContent || '').trim().toLowerCase();

                if(
                    text.includes('enter the q for this record') ||
                    node.matches('.form-hint,.field-hint,[data-form-help-generated]')
                ){
                    node.remove();
                }
            });
        }

        const describedBy=search.getAttribute('aria-describedby');

        if(describedBy){
            describedBy.split(/\s+/).forEach((id)=>{
                const helper=document.getElementById(id);

                if(
                    helper &&
                    (helper.textContent || '').toLowerCase().includes('enter the q for this record')
                ){
                    helper.remove();
                }
            });

            search.removeAttribute('aria-describedby');
        }
    }

    /* Remove old generated/floating sidebar blocks left by previous patches. */
    document.querySelectorAll(
        '.eh-sidebar-extension,[data-sidebar-extension="true"],' +
        '.eh-main-sidebar-links,[data-main-sidebar-links="true"],' +
        '[data-eh-generated-sidebar-link="true"]'
    ).forEach((node)=>node.remove());
});
